  SELECT q FROM jsonb_array_elements('[{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Гостям было скучно и никто не хотел оставаться после десерта.","Сергей не помнил ни отца ни матери и сейчас не узнал бы их при встрече.","В Лондоне каждый день если не дождь то туман или морось или мокрый снег.","В деревнях по праздникам песни поют да хороводы водят.","Учителя не было в классе и дети шумно переговаривались."],"a":[0,1,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 1 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Ему мешали сосредоточиться крики чаек и паровозные гудки и даже тиканье старинных часов.","Мы сидели на террасе и любовались оранжевым закатом и мятно-зелёными очертаниями гор.","Сероглазый король не обманул и скоро произошла долгожданная встреча возлюбленных.","Прогноз обещал грозу и нам пришлось быстро выбираться из леса.","Старые деревья в некоторых странах награждаются медалями за возраст и эти медали вывешиваются на стволах."],"a":[2,3,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 2 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["В случае возникновения аварийной ситуации следует выдернуть шнур выдавить стекло.","Отец встал ни свет ни заря быстро собрался и отправился на охоту.","В доме жарко натоплено и все окна закрыты.","На ужин подали настоящее гусиное жаркое и гости восхищённо благодарили щедрую именинницу.","Больше всего дед любил перечитывать «Полтаву» и «Медного всадника» и «Домик в Коломне»."],"a":[0,1,3],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 3 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Близок локоть да не укусишь.","Нестерпимо хотелось пить и путникам пришлось остановиться у ближайшего ручья.","Редкие прохожие не замечали или не хотели замечать ни багряных вспышек осеннего леса ни ядовитого мерцания фонарей ни чуть слышного пения цикад.","Однажды ты поймешь это сам или люди подскажут.","Семьи Монтекки и Капулетти издревле враждовали и их конфликт стал причиной нелепой бессмысленной гибели юных возлюбленных."],"a":[0,1],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 4 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Запрет на купание в водоёмах касается как прудов так и пресноводных озёр лесных рек.","Издавна люди верили в могущество природы и пытались с помощью мифов постичь её тайны.","Пешеход решил убедиться в безопасности движения остановился и только поэтому столкновения удалось избежать.","Чкалов обнаружил задымление в хвостовой части самолёта и машина в тот же миг потеряла управление.","Далёкие звёзды мерцали над гладью воды да свет маяка тонким лучом рассекал темноту ночи."],"a":[3,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 5 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Род Лермонтовых происходил из Шотландии и восходил к полумифическому барду-пророку Томасу Лермонту.","В пансионе юный поэт ищет родную душу увлекается дружбой то с одним то с другим товарищем.","В отношениях с Натальей Фёдоровной Ивановой Лермонтова угнетает нежелание возлюбленной оценить насыщенность его духовной жизни и глубину его талантливой самобытной поэзии.","Ни время ни расстояния не властны были над глубокими и чистыми чувствами молодого поэта.","Во время ссылки на Кавказ Лермонтов проявлял в боях и бесстрашие и мужество рисковал жизнью."],"a":[2,3],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 6 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Мальчику не хватало родительского тепла и внимания и поэтому он был привязан более всего к няне – Арине Родионовне.","Кто из нас в отрочестве не мечтал о настоящей дружбе и о взаимной любви?!","Критики с воодушевлением приняли как стихи так и рассказы юного поэта.","С каждым осенним днём становилось всё холоднее и дождь всё чаще сменялся мокрым снегом.","В Санкт-Петербурге стало пустынно и даже на Невском проспекте царило странное безмолвие."],"a":[0,2,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 7 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Источником для многих эпизодов и образов «Очарованного странника» являются русские народные сказания и былины а также монастырские легенды.","Иван Флягин прошёл путь многих героев житийной литературы и перемена имени свидетельствует о начале его новой жизни.","Какими чертами обладает герой «Очарованного странника» Н. С. Лескова и чем он оказывается очарован?","В истории Ивана Северьяныча Н. С. Лескова интересовали духовные поиски человека и его личный религиозный опыт.","Жизнь проверяет героя не только на физическую но и на психологическую выносливость."],"a":[0,1,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 8 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Отец и мать Булгакова любили играть на рояле и скрипке и исполнять романсы.","Булгаков успешно сдал экзамены и вскоре он был зачислен на первый курс медицинского факультета Киевского университета.","К ученикам в гимназии обращались на «вы» и разрешали высказывать своё мнение.","Кому это выгодно и кто мог решится на столь отчаянный шаг?","Он хотел было пойти погулять да поленился выходить из тёплой квартиры."],"a":[1,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 9 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16},{"commaPick":true,"q":"Расставьте знаки препинания. Укажите предложения, в которых нужно поставить ОДНУ запятую. Запишите номера этих предложений.","sentences":["Объективная оценка художественного произведения требует как способности глубоко проникать в содержание текста так и умения сопереживать развитого воображения и эстетического чувства.","Детство и юность В. Г. Распутина пришлись на суровые послевоенные годы.","Красота природы Сибири ещё в детстве поразила писателя и стала неотъемлемой спутницей его повестей.","Источниками вдохновения для писателя были родная земля и родной народ а также творчество Ивана Бунина и Фёдора Достоевского.","В последние годы жизни писатель много времени и сил отдавал общественной и публицистической деятельности создавал и художественные произведения."],"a":[3,4],"src":"Баландина-Дудина · ЕГЭ-2025 · Вариант 10 · Задание 16","collection":"Баландина-Дудина · ЕГЭ-2025","taskN":16}]'::jsonb) AS q
),
existing_src AS (
  SELECT DISTINCT q->>'src' AS src
  FROM jsonb_array_elements(
    (SELECT questions FROM quiz_bank_overrides WHERE task_n = 16)
  ) AS q
),
to_add AS (
  SELECT jsonb_agg(q) AS arr
  FROM new_q
  WHERE q->>'src' NOT IN (SELECT src FROM existing_src WHERE src IS NOT NULL)
)
UPDATE quiz_bank_overrides
SET questions = questions || COALESCE((SELECT arr FROM to_add), '[]'::jsonb),
    updated_at = now()
WHERE task_n = 16;

-- Проверка: сколько теперь вопросов и сколько в commaPick формате
DO $$
DECLARE
  total int;
  cp int;
  add_cnt int;
BEGIN
  SELECT jsonb_array_length(questions),
         (SELECT count(*) FROM jsonb_array_elements(questions) q
          WHERE (q->>'commaPick')::boolean IS TRUE),
         (SELECT count(*) FROM jsonb_array_elements(questions) q
          WHERE q->>'src' LIKE 'Баландина-Дудина%')
    INTO total, cp, add_cnt
    FROM quiz_bank_overrides WHERE task_n = 16;
  RAISE NOTICE 'Задание 16: всего %, commaPick %, из них Баландина-Дудина %', total, cp, add_cnt;
END $$;
